// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // No need to call assertionDisputedCallback; the property is that getPrice returns 0.
        assertTrue(c.getPrice(identifier, time, ancillaryData) == 0);
    }
}

